CREATE TABLE IF NOT EXISTS commits (revision INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO commits(revision) VALUES(0);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY, device_id TEXT NOT NULL, location_id TEXT, started_at TEXT NOT NULL, finished_at TEXT NOT NULL, status TEXT NOT NULL, snapshot_hash TEXT NOT NULL, summary TEXT NOT NULL, manifest TEXT NOT NULL, uploaded_at TEXT);
CREATE INDEX IF NOT EXISTS games_location ON games(location_id,finished_at);
CREATE TABLE IF NOT EXISTS game_rounds (id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS rounds_game ON game_rounds(game_id);
CREATE TABLE IF NOT EXISTS game_questions (id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), question_index INTEGER NOT NULL, data TEXT NOT NULL, sha256 TEXT NOT NULL, UNIQUE(game_id,question_index));
CREATE TABLE IF NOT EXISTS login_attempts (ip TEXT PRIMARY KEY, failures INTEGER NOT NULL, window_start INTEGER NOT NULL);
